 const [interviewer,setInterviewer]=useState("");
 const [assessment,setAssessment]=useState("");
 const [result,setResult]=useState<HiringInterview["result"]>("Passed");
 const [hireDate,setHireDate]=useState("");
 const [onboardFileNames,setOnboardFileNames]=useState<Record<string,string>>({});
 const [addRequirementOpen,setAddRequirementOpen]=useState(false);
 const [newRequirement,setNewRequirement]=useState("");
 const [newRequirementRequired,setNewRequirementRequired]=useState(true);
 const [documentKind,setDocumentKind]=useState<"applicant-upload"|"company-signature">("applicant-upload");
 const [selectedCompanyDoc,setSelectedCompanyDoc]=useState("");
 const [companySourceFiles,setCompanySourceFiles]=useState<Record<string,File>>({});
 const [interviewRatings,setInterviewRatings]=useState<Record<string,number>>({});
 const [interviewChecklist,setInterviewChecklist]=useState<Record<string,boolean>>({});
 const screeningCriteria=["Minimum requirements checked","Relevant experience reviewed","Qualifications assessed","Interview documents reviewed"];

 // Keep historical/app-imported positions visible even if their form was not in the new catalog.
 useEffect(()=>{const legacy=Array.from(new Set(records.map(r=>r.role).filter(name=>name&&!forms.some(f=>f.position===name))));if(!legacy.length)return;setForms(previous=>[...previous,...legacy.filter(name=>!previous.some(f=>f.position===name)).map(name=>({id:`legacy-${makeFormId(name)}`,position:name,status:"Draft" as const,minimumYears:0,education:"",qualifications:[],questions:[],onboardingDocuments:[...DEFAULT_ONBOARDING_DOCUMENTS],createdAt:today()}))])},[records,forms,setForms]);
 const visible=records.filter(r=>branch==="All Shops"||r.branch===branch);
 const selected=records.find(r=>r.id===selectedId);
 const assessmentCriteria=useMemo(()=>/technician|mechanic|automotive/i.test(selected?.role||"")?["Technical knowledge","Practical skills","Safety awareness","Problem solving","Communication"]:/advisor|service/i.test(selected?.role||"")?["Customer handling","Vehicle service knowledge","Communication","Problem solving","Process accuracy"]:["Role-specific knowledge","Communication","Problem solving","Reliability","Teamwork"],[selected?.role]);
 const job=forms.find(f=>f.id===positionId);
 const relevant=useMemo(()=>visible.filter(r=>r.role===job?.position&&`${r.name} ${r.id} ${r.email} ${r.education||""}`.toLowerCase().includes(query.toLowerCase())&&(stageFilter==="All"||r.stage===stageFilter)&&(experienceFilter==="All"||(typeof r.relevantYears==="number"&&r.relevantYears>=Number(experienceFilter)))),[visible,job,query,stageFilter,experienceFilter]);
 const stageMatches=(r:ApplicantRecord,tab:CycleTab)=>tab==="applications"?["New Applicant","On Hold"].includes(r.stage):tab==="shortlisted"?r.stage==="Shortlisted":tab==="interviews"?r.stage.includes("Interview")&&!(readInterviews(r).length&&readInterviews(r)[readInterviews(r).length-1].result==="Passed"): ["Rejected","Passed","Hired"].includes(r.stage)||(r.stage.includes("Interview")&&readInterviews(r).length>0&&readInterviews(r)[readInterviews(r).length-1].result!=="Pending");
 const stageCounts=(position:string)=>({applications:visible.filter(r=>r.role===position&&stageMatches(r,"applications")).length,shortlisted:visible.filter(r=>r.role===position&&stageMatches(r,"shortlisted")).length,interviews:visible.filter(r=>r.role===position&&stageMatches(r,"interviews")).length,decisions:visible.filter(r=>r.role===position&&stageMatches(r,"decisions")).length});
 const cycleRecords=relevant.filter(r=>stageMatches(r,cycleTab));
 const todayInterviews=visible.filter(r=>readInterviews(r).some(i=>i.at.slice(0,10)===today()&&i.result==="Pending"));
 const unscheduled=visible.filter(r=>activeCycle(r)&&!readInterviews(r).some(i=>i.result==="Pending"));
 const dueEvaluation=visible.filter(r=>activeCycle(r)&&readInterviews(r).some(i=>i.result==="Pending"&&i.at.slice(0,10)<today()));
 const newApplicants=visible.filter(r=>r.stage==="New Applicant");
 const pendingOnboard=visible.filter(r=>r.stage==="Passed");
 const quickCandidates=quickRecruit==="new"?newApplicants:quickRecruit==="today"?todayInterviews:quickRecruit==="unscheduled"?unscheduled:quickRecruit==="onboard"?pendingOnboard:[];
 const quickNames={new:"New Applications",today:"Interviews Today",unscheduled:"Unscheduled Interviews",onboard:"Pending Onboarding"};
