 {space!=="home"&&<nav className="hire-breadcrumb"><button type="button" onClick={()=>{setSpace("home");setPositionId(null);setSelectedId(null);setBuilder(null);setQuickRecruit(null);setCycleTab("applications")}}><ArrowLeft size={14}/> Recruitment</button><ChevronRight size={14}/><span>{space==="forms"?"Hiring Forms":space==="cycle"?"Hiring Cycle":"Onboarding Process"}</span>{space==="forms"&&job&&<><ChevronRight size={14}/><button onClick={()=>{setSelectedId(null);setBuilder(null);setManualAdd(false)}}>{job.position}</button></>}</nav>}
